mapper.select:
SELECT holiday_id, holiday_date, holiday_name, holiday_kind, version_number
FROM calendar_holidays WHERE holiday_date >= #{startDate} AND holiday_date < #{endDate}
ORDER BY holiday_date, holiday_id

mapper.update:
UPDATE calendar_holidays SET holiday_date = #{holidayDate}, holiday_name = #{holidayName}, holiday_kind = #{holidayKind},
    version_number = version_number + 1
WHERE holiday_id = #{holidayId} AND version_number = #{versionNumber}
